def mention(note):
    if note >= 16:
        return "Très bien"
    if note >= 10:
        return "Admis"
    return "Ajourné"


def bulletin(classe, coefs):
    moyennes = [moyenne_ponderee(notes, coefs) for _, notes in classe]
    return [[nom, m, r, mention(m)] for (nom, _), m, r in zip(classe, moyennes, rangs(moyennes))]
